ottom:0;\r\n        left:0;\r\n        right:0;\r\n        margin:auto;\r\n        transition: transform 0.2s ease;\r\n        object-fit: contain;\r\n    }\r\n\r\n    .video-btn-container img.youtube-btn {\r\n        position:absolute;\r\n        top:0;\r\n        bottom:0;\r\n        left:9%;\r\n        right:0;\r\n        margin:auto;\r\n        width:initial;\r\n        height:initial;\r\n        object-fit: contain;\r\n        z-index:1;\r\n        transition: transform 0.2s ease;\r\n    }\r\n\r\n    .video-btn-container {\r\n        position: absolute;\r\n        height: 52px;\r\n        width: 52px;\r\n        top: 0;\r\n        bottom: 0;\r\n        left:0;\r\n        right:0;\r\n        margin: auto;\r\n        \r\n    }\r\n\r\n    .video-btn-container::before {\r\n        content:'';\r\n        position:absolute;\r\n        width:52px;\r\n        height:52px;\r\n        z-index:1;\r\n        top: 0;\r\n        bottom: 0;\r\n        left:0;\r\n        right:0;\r\n        margin: auto;\r\n        transition: transform 0.2s ease;\r\n        opacity:0.5;\r\n        border-radius:100%;\r\n        background:#000;\r\n        \r\n    }\r\n\r\n    .section-video-item {\r\n        cursor:pointer;\r\n    }\r\n\r\n    .youtube-video-container:hover img.youtube-btn, \r\n    .section-video-item:hover img.youtube-btn {\r\n        transform:scale(1.1);\r\n        transition: transform 0.2s ease;\r\n    }\r\n\r\n    .youtube-video-container:hover .video-btn-container::before, \r\n    .section-video-item:hover .video-btn-container::before {\r\n        transform:scale(1.1);\r\n        transition: transform 0.2s ease;\r\n        \r\n    }\r\n    /* end youtube-video  */\r\n}"]}
